// rt.am = next UID, rt.jg = UID map, rt.S = object types, type.q = instances, type.R = is family, type.Ba = type SID.
var MDZ_UID_RESERVED = 900000000;   // UIDs from here up are reserved (Native MP plugin) and never counted
function mdzFreeUid(rt) { while (rt.jg.hasOwnProperty(String(rt.am))) rt.am++; return rt.am++; }
function mdzUidRepair(rt, save) {
    var saved = (save && save.types) || {}, owner = {}, fixed = [], unclear = [], i, j, t, inst, k, max = rt.am, inSave, prev, move, keep;
    for (i = 0; i < rt.S.length; i++) { t = rt.S[i]; if (t.R) continue;
        for (j = 0; j < t.q.length; j++) { inst = t.q[j]; if (inst.uid < MDZ_UID_RESERVED && inst.uid >= max) max = inst.uid + 1; } }
    rt.am = max;
    for (i = 0; i < rt.S.length; i++) { t = rt.S[i]; if (t.R) continue; inSave = saved.hasOwnProperty(String(t.Ba));
        for (j = 0; j < t.q.length; j++) { inst = t.q[j]; k = String(inst.uid);
            if (!owner.hasOwnProperty(k)) { owner[k] = { inst: inst, inSave: inSave }; continue; }
            prev = owner[k];
            if (prev.inSave === inSave) { unclear.push(k + ' ' + prev.inst.type.name + '/' + inst.type.name); continue; }
            move = inSave ? prev.inst : inst; keep = inSave ? inst : prev.inst;
            move.uid = mdzFreeUid(rt); rt.jg[String(move.uid)] = move; rt.jg[k] = keep;
            owner[k] = { inst: keep, inSave: true }; owner[String(move.uid)] = { inst: move, inSave: false };
            fixed.push(move.type.name + ' ' + k + '->' + move.uid + ' (kept ' + keep.type.name + ')'); } }
    if (window.console && (fixed.length || unclear.length)) console.log('[MDZ] UID repair after load: ' + fixed.length + ' fixed' + (fixed.length ? ': ' + fixed.join(', ') : '') + (unclear.length ? '; left as is: ' + unclear.join(', ') : ''));
    window.MDZUidRepairLog = { fixed: fixed, unclear: unclear, next: rt.am };
}
