var mdzTrueRandom = Math.random, MDZ_FREE = { trigger_spawn: 1, global_respawn: 1, global_respawn_td: 1 };
var mdzMapCreateTick = -1, mdzMapCreateSeen = {}, mdzMapCreateLayout = null;
function mdzMapCreateSkip(name, params, rt) {
    var nm = String(name || "").toLowerCase(), tick, uid, key, at, st;
    if (!mdzSeed.mp) return false;                                  // (a session's: a single player's game is the game's own)
    if (nm !== "create_map_location" && nm !== "erase_map_location") return false;
    if (!rt || typeof rt.Vd !== "number" || !isFinite(rt.Vd)) return false;
    tick = rt.Vd;
    if (rt.wa !== mdzMapCreateLayout) { mdzMapCreateLayout = rt.wa; mdzMapCreateSeen = {}; }
    mdzMapCreateTick = tick;
    uid = params && params.length ? String(params[0]) : "";
    if (!uid) return false;
    key = mdzLevel(rt) + "|" + uid;
    if (nm === "erase_map_location") { delete mdzMapCreateSeen[key]; return false; }
    at = Date.now();
    if (mdzMapCreateSeen[key] && at - mdzMapCreateSeen[key] < 750) {
        if (typeof window !== "undefined") { st = window.MDZMapFixStats || (window.MDZMapFixStats = { skipped: 0, lastUid: "", lastTick: -1 }); st.skipped++; st.lastUid = uid; st.lastTick = tick; }
        return true;
    }
    mdzMapCreateSeen[key] = at;
    return false;
}

// patch 88: in a session the host skips Spawn_NPC while the area of its spawn point is full ("an NPC budget per area"), and
// Car_spawn_at while the admin's vehicle limit is reached
function mdzBudgetSkip(name, params, rt) {
    if (!mdzSeed.mp) return false;
    var nm = String(name || "").toLowerCase(), n = typeof window !== "undefined" && window.MDZNet && window.MDZNet.inst;
    if (!n) return false;
    if (nm === "spawn_npc") return !!(n.npcBudgetFull && n.npcBudgetFull(Number(params && params[0])));
    if (nm === "car_spawn_at") return !!(n.carBudgetFull && n.carBudgetFull());
    return false;
}
